/*
 * The music bank's only translation unit.
 * See MusicBank.h for what ships and why it is one track.
 *
 * THE ASSET
 *
 * `src/assets/music/MusE1M1.inc` is generated by `tools/mus2tracks.py` from
 * `tools/DOOM1.WAD`'s `D_E1M1` lump and committed. It defines the note arrays
 * and the four `MusicTrack` structs in `pixelroot32::audio`; including it here
 * (and nowhere else) keeps one copy of the 34,320 B in flash. The include is
 * `const`, so it is .rodata, not .bss.
 *
 * The generated file is the source of truth for tempo and pitch. This file
 * only answers the id lookup; it does not reshape the data.
 */
#include "doomc/MusicBank.h"

#include <pixelroot32/apu/AudioMusicTypes.h>

#include "sounds.h"

#include "assets/music/MusE1M1.inc"

namespace doom {
namespace doomc {

const pixelroot32::audio::MusicTrack* musicBankTrack(int music_id) {
    if (music_id == mus_e1m1) {
        return &pixelroot32::audio::kMusE1M1;
    }
    return nullptr;
}

}  // namespace doomc
}  // namespace doom
